(3414106, 476171, 74747, '<td valign="top">I like this! It appears very mysterious.</td>', 'I like this! It appears very mysterious.', '2007-02-28 13:47:00.000000', NULL, 1),
(3414109, 475866, 74747, '<td valign="top">Creepy! But I like it!</td>', 'Creepy! But I like it!', '2007-02-28 13:47:26.000000', NULL, 1),
(3414112, 474947, 74747, '<td valign="top">I really like the shadows.</td>', 'I really like the shadows.', '2007-02-28 13:48:22.000000', NULL, 1),
(3414116, 475775, 74747, '<td valign="top">I love night shots. Good job!</td>', 'I love night shots. Good job!', '2007-02-28 13:50:26.000000', NULL, 1),
(3414117, 476183, 74747, '<td valign="top">I love the effect!</td>', 'I love the effect!', '2007-02-28 13:50:38.000000', NULL, 1),
(3414119, 476130, 74747, '<td valign="top">At first it was hard to tell what this was...maybe if you included a little more profile or hair. But I like it!</td>', 'At first it was hard to tell what this was...maybe if you included a little more profile or hair. But I like it!', '2007-02-28 13:51:05.000000', NULL, 1),
(3414121, 476858, 74747, '<td valign="top">I love the effect the lights had. Nice touch.</td>', 'I love the effect the lights had. Nice touch.', '2007-02-28 13:52:24.000000', NULL, 1),
(3414126, 476048, 74747, '<td valign="top">This is something I haven''t seen! I love it!</td>', 'This is something I haven''t seen! I love it!', '2007-02-28 13:54:05.000000', NULL, 1),
(3414128, 473875, 74747, '<td valign="top">Even though it appears to be a simple picture, the light really has a great affect.</td>', 'Even though it appears to be a simple picture, the light really has a great affect.', '2007-02-28 13:55:30.000000', NULL, 1),
(3414132, 474003, 74747, '<td valign="top">I really like the look on his face. It keeps you guessing what he''s thinking.</td>', 'I really like the look on his face. It keeps you guessing what he''s thinking.', '2007-02-28 13:56:44.000000', NULL, 1),
(3414138, 473207, 74747, '<td valign="top">It looks like the cat is posing!</td>', 'It looks like the cat is posing!', '2007-02-28 13:59:56.000000', NULL, 1),
(3414177, 476661, 49109, '<td valign="top">nicely done, though not the perfect example of Low Key</td>', 'nicely done, though not the perfect example of Low Key', '2007-02-28 14:16:10.000000', NULL, 1),
(3414197, 476783, 70369, '<td valign="top">Beautiful subject to use with low key lighting. I think the white tips lend itself perfectly for this set up.I like the crop &amp; your choice of shooting them while falling over. 10</td>', 'Beautiful subject to use with low key lighting. I think the white tips lend itself perfectly for this set up.I like the crop & your choice of shooting them while falling over. 10', '2007-02-28 14:24:41.000000', NULL, 1),
(3414200, 476550, 70369, '<td valign="top">great use of low key lighting.I think I would like this better with out the water drops as some are distracting. imho. ;-). 8</td>', 'great use of low key lighting.I think I would like this better with out the water drops as some are distracting. imho. ;-). 8', '2007-02-28 14:25:22.000000', NULL, 1),
(3414206, 473144, 49109, '<td valign="top">interesting processing, yet not low key</td>', 'interesting processing, yet not low key', '2007-02-28 14:27:13.000000', NULL, 1),
(3414207, 476767, 70369, '<td valign="top">This is certainly low key. I wonder what it looked like in b &amp; w. The fingers are a too red for my taste.It kinda pulls my eye to them and I really think it should be the dice.:-). 6 for me.</td>', 'This is certainly low key. I wonder what it looked like in b & w. The fingers are a too red for my taste.It kinda pulls my eye to them and I really think it should be the dice.:-). 6 for me.', '2007-02-28 14:27:15.000000', NULL, 1),
