(3427822, 476872, 32968, '<td valign="top">How many crisis line phone numbers have you received since the voting started? Nice low key submission. I like the contrasting glare off the blade, but I have to be honest, I''m not groovin'' on the overall emotion from this pic. You''ll definitely be striking some hearts close to home tho. It''s got strong emotive qualities. I truly hope this is all staged. If not, find help :)</td>', 'How many crisis line phone numbers have you received since the voting started? Nice low key submission. I like the contrasting glare off the blade, but I have to be honest, I''m not groovin'' on the overall emotion from this pic. You''ll definitely be striking some hearts close to home tho. It''s got strong emotive qualities. I truly hope this is all staged. If not, find help :)', '2007-03-04 13:42:55.000000', NULL, 1),
(3427832, 475842, 10867, '<td valign="top">I think I would have preferred the light to be on her face, rather than on her dress.</td>', 'I think I would have preferred the light to be on her face, rather than on her dress.', '2007-03-04 13:46:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3427836, 475962, 32968, '<td valign="top">Bit too dark. Crop out the empty space might help to "lighten" the appearance of the photo.</td>', 'Bit too dark. Crop out the empty space might help to "lighten" the appearance of the photo.', '2007-03-04 13:47:46.000000', NULL, 1),
(3427839, 475260, 32968, '<td valign="top">Very small image. I can''t really get a good view of it. It takes some figgering to get the sizing thing down. There''s some good tutorials on the subject tho. Good luck.</td>', 'Very small image. I can''t really get a good view of it. It takes some figgering to get the sizing thing down. There''s some good tutorials on the subject tho. Good luck.', '2007-03-04 13:50:43.000000', NULL, 1),
(3427841, 476760, 32968, '<td valign="top">Bring Saturn up in to picture a bit more. Maybe by cropping some of the empty space out. Nice clear picture. Looks very realistic.</td>', 'Bring Saturn up in to picture a bit more. Maybe by cropping some of the empty space out. Nice clear picture. Looks very realistic.', '2007-03-04 13:52:58.000000', NULL, 1),
(3427842, 476846, 70514, '<td valign="top">That''s a great shot, love the color you captured!</td>', 'That''s a great shot, love the color you captured!', '2007-03-04 13:54:06.000000', NULL, 1),
(3427843, 472897, 70514, '<td valign="top">Great detail.</td>', 'Great detail.', '2007-03-04 13:54:18.000000', NULL, 1),
(3427849, 476058, 32968, '<td valign="top">Beautiful clarity, colors and detail. I''d crop a bit more of the black space around it tho, just to bring more balance to the photo.</td>', 'Beautiful clarity, colors and detail. I''d crop a bit more of the black space around it tho, just to bring more balance to the photo.', '2007-03-04 13:58:01.000000', NULL, 1),
(3427863, 473203, 32968, '<td valign="top">I''m stumped. For some reason, this looks like a model car to me. Can''t tell if it''s life-size or not. The little dent makes me think it''s real, but the rest of it doesn''t. Nice pic either way.</td>', 'I''m stumped. For some reason, this looks like a model car to me. Can''t tell if it''s life-size or not. The little dent makes me think it''s real, but the rest of it doesn''t. Nice pic either way.', '2007-03-04 14:03:20.000000', NULL, 1),
(3427894, 475256, 72714, '<td valign="top">Absolutely gorgeous lighting and texture! The little dog is gorgeous too and is being the perfect model. I like the catchlight in the eye as well.</td>', 'Absolutely gorgeous lighting and texture! The little dog is gorgeous too and is being the perfect model. I like the catchlight in the eye as well.', '2007-03-04 14:18:46.000000', NULL, 1),
(3427898, 476042, 72714, '<td valign="top">Perfect lighting and pose! One of my highest scores!</td>', 'Perfect lighting and pose! One of my highest scores!', '2007-03-04 14:20:39.000000', NULL, 1),
(3427901, 476783, 72714, '<td valign="top">An awesome photo! This is my favourite! I tried to stand on my head to see what it would look like the other way up as the orientation looked a little odd at first, but this definately works! Well done!</td>', 'An awesome photo! This is my favourite! I tried to stand on my head to see what it would look like the other way up as the orientation looked a little odd at first, but this definately works! Well done!', '2007-03-04 14:20:58.000000', NULL, 1),
(3427904, 475843, 72714, '<td valign="top">I love the lighting, the crop and the expression on the models face. I would have preferred a little less grain, but an excellent shot none the less.</td>', 'I love the lighting, the crop and the expression on the models face. I would have preferred a little less grain, but an excellent shot none the less.', '2007-03-04 14:22:09.000000', NULL, 1),
(3427905, 473902, 72714, '<td valign="top">I like the reflection in the raindrop and how it adds a highlight to the darkest part of the photo. Well photographed.</td>', 'I like the reflection in the raindrop and how it adds a highlight to the darkest part of the photo. Well photographed.', '2007-03-04 14:23:19.000000', NULL, 1),
(3427910, 475842, 72714, '<td valign="top">This is really a beautiful shot. I like the inclusion of the texture in the wall behind the bride and the soft light on her face. IMO, her back and the side of her face should have had slightly more light as it feels a bit ''solid''. The saving grace is the very fine highlight on the edge of her veil which fantastic. Well captured</td>', 'This is really a beautiful shot. I like the inclusion of the texture in the wall behind the bride and the soft light on her face. IMO, her back and the side of her face should have had slightly more light as it feels a bit ''solid''. The saving grace is the very fine highlight on the edge of her veil which fantastic. Well captured', '2007-03-04 14:27:14.000000', NULL, 1),
(3427949, 476462, 35613, '<td valign="top">Almost too low key, but very beautiful.</td>', 'Almost too low key, but very beautiful.', '2007-03-04 14:44:33.000000', NULL, 1),
