INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3456356, 476091, 40973, '<td valign="top">I gave this a 7 - I''m not necessarily of fan of softness but loved the soft of this - it fits well with the subject - makes you want to reach out and give a tickle under the chin.</td>', 'I gave this a 7 - I''m not necessarily of fan of softness but loved the soft of this - it fits well with the subject - makes you want to reach out and give a tickle under the chin.', '2007-03-13 12:19:55.000000', NULL, 0),
(3456480, 476026, 66515, '<td valign="top">22nd out of 351 and no comments? Weird. Usually you should get at least one or two "Good shot" type of comments anyways. <br/> <br/>I like the lighting you''ve presented here. Its quite subtle. The fade to black on the left of the face is nice as well. This works well for the challenge. <br/> <br/>Things to fix? I guess you didn''t necessarily need to crop off the top of the head. Then again I am guessing its a self-portrait so it is a little harder to frame the shot perfectly.</td>', '22nd out of 351 and no comments? Weird. Usually you should get at least one or two "Good shot" type of comments anyways.  I like the lighting you''ve presented here. Its quite subtle. The fade to black on the left of the face is nice as well. This works well for the challenge.  Things to fix? I guess you didn''t necessarily need to crop off the top of the head. Then again I am guessing its a self-portrait so it is a little harder to frame the shot perfectly.', '2007-03-13 13:10:54.000000', NULL, 0),
(3456912, 476129, 1024, '<td valign="top">Greetings from tyhe Critique Club.<br/> <br/>This is a wonderful sunset photo, the colors are brilliant and range all the way from the darkest red to pale blue.  You have captured alot of detail in the clouds.<br/> <br/>The one thing that I wish I coulkd change is the lack if detail in the foreground.  Setsets are beautiful things, but without some sense of place or feel for where it was taken, they pretty much become all the same.  If I stare at the photograph lonf enougn I can see the horizon, but nothing at all below that.  My personal choice would be to sacrifice a bit of the rich color of the sky to obtain more detail in the foreground.<br/> <br/>For other situations like this, a half neutral density filter might just block some on th light on the top half of the photo, and alow mire light on the bpttom.  I am jusy making an educated guess, but it might be worth playing with.<br/> <br/></td>', 'Greetings from tyhe Critique Club. This is a wonderful sunset photo, the colors are brilliant and range all the way from the darkest red to pale blue.  You have captured alot of detail in the clouds. The one thing that I wish I coulkd change is the lack if detail in the foreground.  Setsets are beautiful things, but without some sense of place or feel for where it was taken, they pretty much become all the same.  If I stare at the photograph lonf enougn I can see the horizon, but nothing at all below that.  My personal choice would be to sacrifice a bit of the rich color of the sky to obtain more detail in the foreground. For other situations like this, a half neutral density filter might just block some on th light on the top half of the photo, and alow mire light on the bpttom.  I am jusy making an educated guess, but it might be worth playing with. ', '2007-03-13 16:06:34.000000', NULL, 0),
(3458507, 474718, 60505, '<td valign="top">like the photo, pity about the DQ. silly rules!<br/></td>', 'like the photo, pity about the DQ. silly rules!', '2007-03-14 02:39:09.000000', NULL, 0),
